
import {Options, Vue } from 'vue-class-component';
import {Params} from "../model/param"
import {TaxBracket} from  "../model/marginal_tax"

@Options({
  props: {
    msg: String,
    params: Params
  },
})
export default class InputParam extends Vue {
  msg!: string;
  params!: Params;
  deposit_percent=20;
  config = {
    debug: false,
    masked: false,
    prefix: '',
    suffix: '',
    thousands: ',',
    decimal: '.',
    precision: 0,
    disableNegative: false,
    disabled: false,
    min: null,
    max: null,
    allowBlank: false,
    minimumNumberOfCharacters: 0,
    modelModifiers: {
        number: true,
    },
    shouldRound: true,
    focusOnRight: false,
  }
  tax_rate(enable: boolean, income: number) : string {
      if (enable) {
          let pct = TaxBracket.GetPercent(income)*100;
          return `${pct}%`;
      } else {
          return "N/A";
      }
  }

}
