
import { Options, Vue } from 'vue-class-component';

interface ToggleOption {
  key: string;
  label: string;
}

@Options({
  props: {
    options: Array as () => ToggleOption[],
    modelValue: String as () => string
  },
  emits: ['update:modelValue']
})
export default class ToggleSwitchGroup extends Vue {
  options!: ToggleOption[];
  modelValue!: string;

  get selectedOption(): string {
    return this.modelValue || this.options[0].key;
  }

  toggleOption(key: string): void {
      //this.modelValue = key;
      this.$emit('update:modelValue', key);
  }
}
