
import { Options, Vue } from 'vue-class-component';

import * as d3 from 'd3';
import { sankey, sankeyLinkHorizontal, SankeyGraph, SankeyNode, SankeyLink } from 'd3-sankey';

import {Expense} from "../model/expense"
import ToggleSwitchGroup from './ToggleSwitchGroup.vue';

import { Params } from '../model/param';
import { watch } from 'vue';

interface FlowNode {
  name: string;
  actualValue?: number; // Store the real value to avoid formatting hacks
}

interface FlowLink {
  source: number;
  target: number;
  value: number;
}

@Options({
  components: {
    ToggleSwitchGroup
  },
  props: {
    title: String,
    view_period: Number,
    expenses: Array,
    params: Params,
  }
})
export default class SankeyDiagram extends Vue {

  view_period!: number;
  expenses!: Expense[];
  params!: Params;
  title!: string;
  private debounceTimer: number | null = null;
  describe_period=Expense.describe_period;
    
    categoryOptions = [
        {key: 'period_expense',
         label: `Amount per ${this.describe_period(this.view_period)}` ,
         desc: ""
        },
        {key: 'hold_expense',
         label: `Amount commited while holding` ,
         desc: ""
        },
        {key: 'total_expense',
         label: `Amount commited with loan` ,
         desc: ""
        }
    ];
    selected_category: string = this.categoryOptions[0].key;

  mounted(): void {
    this.renderSankey();

    // Watch for changes and re-render with debouncing
    watch(() => [this.expenses, this.view_period, this.params, this.selected_category], () => {
      if (this.debounceTimer !== null) {
        clearTimeout(this.debounceTimer);
      }
      this.debounceTimer = window.setTimeout(() => {
        this.renderSankey();
        this.debounceTimer = null;
      }, 150);
    }, { deep: true });
  }

  renderSankey(): void {
    // Update category label based on current period
    this.categoryOptions[0].label = `Amount per ${this.describe_period(this.view_period)}`;

    // Validate required props - return early if invalid
    if (!this.expenses || !this.expenses.length || !this.params || this.view_period === undefined) {
      return;
    }

    const container = this.$refs.sankeyRef as HTMLElement;
    if (!container) return;

    // Clear previous chart
    d3.select(container).selectAll('*').remove();

    // Prepare data
    const { nodes, links } = this.prepareData();

    // Set dimensions
    const windowWidth = window.innerWidth;
    const windowHeight = window.innerHeight;

    const margin = { winner: 10, wouter: 90, houter: 90, hinner: 10 };
    const width = windowWidth - margin.winner - margin.wouter;
    const height = windowHeight - margin.hinner - margin.houter;

    // Create SVG
    const svg = d3.select(container)
      .append('svg')
      .attr('width', width + margin.winner*2)
      .attr('height', height  + margin.hinner*2)
      .append('g')
      .attr('transform', `translate(${margin.winner},${margin.hinner})`);

    // Create sankey layout with increased padding for better label spacing
    const sankeyLayout = sankey<FlowNode, FlowLink>()
      .nodeWidth(15)
      .nodePadding(10)  // Increased from 10 to 25 to prevent label overlap on small nodes
      .extent([[1, 1], [width - 1, height - 5]]);

    const graph: SankeyGraph<FlowNode, FlowLink> = sankeyLayout({
      nodes: nodes.map(d => ({ ...d })),
      links: links.map(d => ({ ...d }))
    });

    // Color scale
    const color = d3.scaleOrdinal(d3.schemeCategory10);

    // Add links
    svg.append('g')
      .selectAll('path')
      .data(graph.links)
      .join('path')
      .attr('d', sankeyLinkHorizontal())
      .attr('stroke', (d: SankeyLink<FlowNode, FlowLink>) => {
        const sourceNode = d.source as SankeyNode<FlowNode, FlowLink>;
        return color(sourceNode.name);
      })
      .attr('stroke-width', (d: SankeyLink<FlowNode, FlowLink>) => Math.max(1, d.width || 0))
      .attr('fill', 'none')
      .attr('opacity', 0.5)
      .append('title')
      .text((d: SankeyLink<FlowNode, FlowLink>) => {
        const sourceNode = d.source as SankeyNode<FlowNode, FlowLink>;
        const targetNode = d.target as SankeyNode<FlowNode, FlowLink>;
        // For links, create a temporary node with the link value
        const linkNode = { name: 'Link', value: d.value } as SankeyNode<FlowNode, FlowLink>;
        return `${sourceNode.name} → ${targetNode.name}\n${this.formatCurrency(linkNode)}`;
      });

    // Add nodes
    const node = svg.append('g')
      .selectAll('rect')
      .data(graph.nodes)
      .join('g');

    node.append('rect')
      .attr('x', (d: SankeyNode<FlowNode, FlowLink>) => d.x0 || 0)
      .attr('y', (d: SankeyNode<FlowNode, FlowLink>) => d.y0 || 0)
      .attr('height', (d: SankeyNode<FlowNode, FlowLink>) => (d.y1 || 0) - (d.y0 || 0))
      .attr('width', (d: SankeyNode<FlowNode, FlowLink>) => (d.x1 || 0) - (d.x0 || 0))
      .attr('fill', (d: SankeyNode<FlowNode, FlowLink>) => color(d.name))
      .attr('opacity', 0.8)
      .append('title')
      .text((d: SankeyNode<FlowNode, FlowLink>) => `${d.name} : ${this.formatCurrency(d)}`);

    // Add labels
    node.append('text')
      .attr('x', (d: SankeyNode<FlowNode, FlowLink>) => (d.x0 || 0) < width / 2 ? (d.x1 || 0) + 6 : (d.x0 || 0) - 6)
      .attr('y', (d: SankeyNode<FlowNode, FlowLink>) => ((d.y1 || 0) + (d.y0 || 0)) / 2)
      .attr('dy', '0.35em')
      .attr('text-anchor', (d: SankeyNode<FlowNode, FlowLink>) => (d.x0 || 0) < width / 2 ? 'start' : 'end')
      .text((d: SankeyNode<FlowNode, FlowLink>) => `${d.name} : ${this.formatCurrency(d)}`)
      .style('font-size', '12px')
      .style('font-weight', 'bold');

  }

  calcValue(expense: Expense) : number  {
      if (this.selected_category == 'period_expense') {
          return expense.periodic(this.params.config.hold_term, this.view_period);
      }
      if (this.selected_category == 'hold_expense') {
          return expense.accumulated(this.params.config.hold_term);
      }
      if (this.selected_category == 'total_expense') {
          return expense.upfront_amount;
      }
      return 0;
  }

  /**
   * Collect all nodes from the expense tree
   * Returns nodes array and a map of node names to their indices
   */
  private collectAllNodes(): { nodes: FlowNode[], nodeIndexMap: Map<string, number> } {
    const nodes: FlowNode[] = [];
    const nodeIndexMap: Map<string, number> = new Map();
    let nextIndex = 0;

    const collectNodesRecursive = (expense: Expense): void => {
      const expenseValue = this.calcValue(expense);

      // Skip zero-value nodes entirely
      if (expenseValue === 0) {
        return;
      }

      // Add primary node if not already seen
      if (!nodeIndexMap.has(expense.label)) {
        nodeIndexMap.set(expense.label, nextIndex++);
        nodes.push({ name: expense.label, actualValue: expenseValue });
      }

      // Process children and create intermediate nodes for deductions
      if (expense.expenses) {
        // Calculate sums for additions and deductions
        let additionsSum = 0;
        let deductionsSum = 0;

        expense.expenses.forEach(([op, child]) => {
          const childValue = this.calcValue(child);
          if (op === "+") {
            additionsSum += childValue;
          } else if (op === "-") {
            deductionsSum += childValue;
          }
        });

        // Only create intermediate nodes if we have non-zero deductions AND additions
        if (deductionsSum > 0 && additionsSum > 0) {
          const grossLabel = `Gross ${expense.label}`;
          const deductionsLabel = `${expense.label} Deductions`;

          if (!nodeIndexMap.has(grossLabel)) {
            nodeIndexMap.set(grossLabel, nextIndex++);
            nodes.push({ name: grossLabel });
          }

          if (!nodeIndexMap.has(deductionsLabel)) {
            nodeIndexMap.set(deductionsLabel, nextIndex++);
            nodes.push({ name: deductionsLabel });
          }
        }

        // Recursively collect from children (will skip zero-value children)
        expense.expenses.forEach(([, childExpense]) => {
          collectNodesRecursive(childExpense);
        });
      }
    };

    this.expenses.forEach(expense => collectNodesRecursive(expense));
    return { nodes, nodeIndexMap };
  }

  /**
   * Build all links between nodes
   */
  private buildAllLinks(nodeIndexMap: Map<string, number>): FlowLink[] {
    const links: FlowLink[] = [];
    const linkedPairs = new Set<string>();

    const createLink = (sourceIdx: number, targetIdx: number, value: number): void => {
      const linkKey = `${sourceIdx}-${targetIdx}`;
      if (!linkedPairs.has(linkKey) && value > 0) {
        links.push({ source: sourceIdx, target: targetIdx, value });
        linkedPairs.add(linkKey);
      }
    };

    const buildLinksRecursive = (expense: Expense): void => {
      if (!expense.expenses || expense.expenses.length === 0) {
        return;
      }

      const expenseValue = this.calcValue(expense);
      if (expenseValue === 0) {
        return;
      }

      // Calculate sums for additions and subtractions
      let additionsSum = 0;
      let subtractionsSum = 0;

      expense.expenses.forEach(([op, childExpense]) => {
        const childValue = this.calcValue(childExpense);
        if (op === "+") {
          additionsSum += childValue;
        } else if (op === "-") {
          subtractionsSum += childValue;
        }
      });

      const expenseIdx = nodeIndexMap.get(expense.label);
      const hasDeductions = subtractionsSum > 0;

      // Determine target indices based on whether we have deductions
      const additionsTargetIdx = hasDeductions
        ? nodeIndexMap.get(`Gross ${expense.label}`)
        : expenseIdx;
      const deductionsTargetIdx = nodeIndexMap.get(`${expense.label} Deductions`);

      // Create intermediate links for deductions flow
      if (hasDeductions && additionsTargetIdx !== undefined && deductionsTargetIdx !== undefined && expenseIdx !== undefined) {
        createLink(additionsTargetIdx, expenseIdx, additionsSum);
        createLink(expenseIdx, deductionsTargetIdx, subtractionsSum);
      }

      // Create links from children to parent
      expense.expenses.forEach(([op, childExpense]) => {
        const childValue = this.calcValue(childExpense);
        const childIdx = nodeIndexMap.get(childExpense.label);

        if (childIdx === undefined) {
          return;
        }

        if (op === "+") {
          if (additionsTargetIdx !== undefined) {
            createLink(childIdx, additionsTargetIdx, childValue);
          }
        } else if (op === "-") {
          if (deductionsTargetIdx !== undefined) {
            createLink(childIdx, deductionsTargetIdx, childValue);
          }
        }

        // Recurse into children
        buildLinksRecursive(childExpense);
      });
    };

    this.expenses.forEach(expense => buildLinksRecursive(expense));
    return links;
  }

  prepareData(): { nodes: FlowNode[], links: FlowLink[] } {
    const { nodes, nodeIndexMap } = this.collectAllNodes();
    const links = this.buildAllLinks(nodeIndexMap);
    return { nodes, links };
  }

  formatCurrency(node: SankeyNode<FlowNode, FlowLink>): string {
    // Use actualValue if available, otherwise fall back to the D3-calculated value
    // Deductions nodes show half their flow value since they appear in both directions
    const name = node.name;
    const d3Value = node.value || 0;
    const actualValue = (node as FlowNode).actualValue;

    const displayValue = actualValue !== undefined
      ? actualValue
      : (name.includes('Deductions') ? d3Value / 2 : d3Value);

    const currency = this.params.location.currency;
    const symbol = currency === 'JPY' ? '¥' : '$';
    const divisor = currency === 'JPY' ? 10000 : 1000;

    if (displayValue >= divisor) {
      const suffix = currency === 'JPY' ? '万' : 'k';
      const formatted = (displayValue / divisor).toFixed(3);
      return `${symbol}${formatted}${suffix}`;
    } else {
      const formatted = Math.round(displayValue);
      return `${symbol}${formatted}`;
    }
  }
}
