
import {Options, Vue} from 'vue-class-component';
import {Expense} from "../model/expense";

@Options({
    emits: [
           "update"
    ]
})
export default class TimeRange extends Vue {
    ONE_YEAR=Expense.ONE_YEAR;
    ONE_MONTH=Expense.ONE_MONTH;
    ONE_WEEK=Expense.ONE_WEEK;
    time_range = this.ONE_WEEK;

    selectTimeRange(value: number): void {
        this.time_range = value;
        this.$emit('update', value);
    }
}
