
import {Vue, Options} from 'vue-class-component';
import {Expense} from "../model/expense"
import {format as money_format} from 'v-money3';
import {Params} from "../model/param"

const config = {
    debug: false,
    masked: false,
    prefix: '',
    suffix: '',
    thousands: ',',
    decimal: '.',
    precision: 0,
    disableNegative: false,
    disabled: false,
    min: null,
    max: null,
    allowBlank: false,
    minimumNumberOfCharacters: 0,
    modelModifiers: {
        number: false,
    },
    shouldRound: true,
    focusOnRight: false,
}


@Options({
    name : "ViewExpense",
    props: {
      visible: Boolean,
      view_period: Number,
      expense: Expense,
      params: Params,
      operation: String,
      depth: Number,
      id: Number,
  }
})

export default class ViewExpense extends Vue {
    alias_money_format = money_format;
    params!: Params;
    depth!: number;
    child_visible: boolean = this.depth == 0;

    format(v: number) : string {
      return  this.params.location.currency +  money_format(v, config);
    }
    periodic_amount(expense: Expense, params: Params, view_period: number) : number {
       // Only show repeating costs per period, no amortization
        return expense.periodic(params.config.hold_term, view_period);
    }
    accumulated_cost(expense: Expense, params: Params) : number {
       // Total costs over the holding term: upfront + (repeating costs * hold_term)
        return expense.accumulated(params.config.hold_term);
    }
    toggle_child(): void {
        if (this.depth != 0) {
            this.child_visible = !this.child_visible;
        }
    }
}
