
import {Options, Vue} from 'vue-class-component';

@Options({
  props: {
    option1: String,
    option2: String,
    enable_option1: Boolean
  },
  emits: [
    "update"
  ]
})
export default class TwoWaySwitch extends Vue {
  option1!: string;
  option2!: string;
  enable_option1!: boolean;

  selectOption(value: boolean): void {
    this.$emit('update', value);
  }
}

